/** Generated types and spec from the reviewed fade_market.wasm. No deployment or signing client. */
import { Buffer } from 'buffer';
import { Spec } from '@stellar/stellar-sdk/contract';
import type { u32,u64,i128,Option } from '@stellar/stellar-sdk/contract';
export const Errors = {
  1: {message:"NotFound"},
  2: {message:"InvalidState"},
  3: {message:"InvalidTerms"},
  4: {message:"InvalidWindow"},
  5: {message:"BadKey"},
  6: {message:"WrongEpoch"},
  7: {message:"WrongSequence"},
  8: {message:"PriceExceeded"},
  9: {message:"ActiveReservation"},
  10: {message:"UnknownAsset"},
  11: {message:"InvalidDestination"},
  12: {message:"Overflow"},
  13: {message:"Accounting"},
  14: {message:"ArchiveUnavailable"},
  15: {message:"WrongNetwork"},
  16: {message:"Unauthorized"}
}


export interface Offer {
  deadline_ledger: u32;
  id: u64;
  reservation: ReservationState;
  seller: string;
  /**
 * Monotonic across cancellation/expiry; old permits cannot return.
 */
sequence: u64;
  settled_price: Option<i128>;
  settled_to: Option<string>;
  start_ledger: u32;
  /**
 * 0 open, 1 reserved, 2 settled, 3 refunded.
 */
state: u32;
  terms: OfferTerms;
  terms_hash: Buffer;
}


export interface Merchant {
  epoch: u32;
  public_key: Buffer;
  seller: string;
}


export interface ActiveSlot {
  lease_until: u32;
  offer_id: u64;
  sequence: u64;
}


/**
 * Immutable creation terms. Zero lease_ledgers disables remote reservations.
 * metadata_hash commits the separately signed shop/product/pickup description.
 */
export interface OfferTerms {
  asset: string;
  duration_ledgers: u32;
  floor_price: i128;
  lease_ledgers: u32;
  metadata_hash: Buffer;
  pot: i128;
  slope_den: i128;
  slope_num: i128;
  start_price: i128;
}


export interface Reservation {
  claimant: string;
  claimed_at: u32;
  lease_until: u32;
  merchant: Merchant;
  price: i128;
  sequence: u64;
}


export interface MarketConfig {
  assets: Array<string>;
  max_lease_ledgers: u32;
  max_offer_ledgers: u32;
  max_receipt_ledgers: u32;
}



export interface PickupReceipt {
  claimant: string;
  key_epoch: u32;
  /**
 * price <= max_price; a negative bound requires at least that reward.
 */
max_price: i128;
  nonce: Buffer;
  offer_id: u64;
  sequence: u64;
  terms_hash: Buffer;
  valid_from: u32;
  valid_until: u32;
}

export type ReservationState = {tag: "Empty", values: void} | {tag: "Active", values: readonly [Reservation]};


export interface ReservationPermit {
  lease_until: u32;
  receipt: PickupReceipt;
}



